import os
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

os.environ["CXX"] = "hipcc"

batch_size = 64
in_channels = 64
out_channels = 128
height, width = 128, 128
kernel_size = 3

custom_activation_cpp_source = """
#include &lt;hip/hip_runtime.h&gt;

__device__ float softplus(float input, float beta, float threshold) {
  float z = beta * input - threshold;
  float sp;
  if (z > threshold) {
    sp = input;
  } else {
    float exp_z = (z &lt; 0.0f) ? expf(z) : 1.0f;
    if (z &gt;= 0.0f) {
      sp = (z + log1pf(exp_z)) / beta;
    } else {
      sp = log1pf(exp_z) / beta;
    }
  }
  return sp;
}

__global__ void custom_activation_kernel(const float* input, float* output, int64_t size) {
  int64_t idx = blockIdx.x * blockDim.x + threadIdx.x;
  if (idx &lt; size) {
    float x = input[idx];
    float sp = softplus(x, 1.0f, 20.0f);
    float tx = tanhf(sp);
    output[idx] = x * tx;
  }
}

torch::Tensor custom_activation_hip(torch::Tensor input) {
  auto output = torch::empty_like(input);
  int64_t size = input.numel();
  const int block_size = 256;
  dim3 block(block_size);
  dim3 grid((size + block_size - 1) / block_size);
  custom_activation_kernel&lt;&lt;&lt;grid, block&gt;&gt;&gt;(input.data_ptr&lt;float&gt;(), output.data_ptr&lt;float&gt;(), size);
  return output;
}
"""

custom_act = load_inline(
    name="custom_act",
    cpp_sources=custom_activation_cpp_source,
    functions=["custom_activation_hip"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, eps=1e-5, momentum=0.1):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.bn = nn.BatchNorm2d(out_channels, eps=eps, momentum=momentum)
        self.custom_act = custom_act

    def forward(self, x):
        x = self.conv(x)
        x = self.custom_act.custom_activation_hip(x)
        x = self.bn(x)
        return x

def get_inputs():
    return [torch.rand(batch_size, in_channels, height, width)]

def get_init_inputs():
    return [in_channels, out_channels, kernel_size]

